import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.MBzO9hES.js";const m=JSON.parse('{"title":"Français : règles et vocabulaire","description":"","frontmatter":{},"headers":[],"relativePath":"i18n/glossary/fr.md","filePath":"i18n/glossary/fr.md"}'),o={name:"i18n/glossary/fr.md"};function i(s,t,n,l,u,c){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="francais-regles-et-vocabulaire" tabindex="-1">Français : règles et vocabulaire <a class="header-anchor" href="#francais-regles-et-vocabulaire" aria-label="Permalink to &quot;Français : règles et vocabulaire&quot;">​</a></h1><p>Les règles de <code>en.md</code> s’appliquent aussi (identifiants, placeholders, pluriels, apostrophe typographique). Cette page fixe ce qui est propre au français. Quand un terme manque, ajoutez-le ici dans la même pull request que la traduction.</p><h2 id="registre" tabindex="-1">Registre <a class="header-anchor" href="#registre" aria-label="Permalink to &quot;Registre&quot;">​</a></h2><ul><li><strong>L’application vouvoie</strong> : « Vos séances », « Allumez d’abord l’appareil ».</li><li><strong>Poulpy tutoie</strong> (<code>domain</code> → <code>poulpy.*</code>) : « Termine une séance et j’allume mon premier tentacule ». C’est un personnage qui parle, pas l’interface.</li><li>Les consignes d’exercice (<code>catalog</code> → <code>instructions</code>) vouvoient à l’impératif : « Tenez la charge contre la poitrine ».</li><li><strong>Pas de genre pour la personne</strong> : d’abord une tournure neutre, souvent l’impératif (« Allongez-vous sur le dos » plutôt que « Allongé sur le dos », « On y va ? » plutôt que « Prêt ? »). Quand aucune ne sonne naturel, l’écriture inclusive au point médian est permise sur un mot court (« Prêt·e ? », « Bienvenue, sportif·ve »), jamais de parenthèses ni de barre oblique. Évitez-la dans les phrases longues : les lecteurs d’écran la lisent mal. Poulpy, lui, est masculin : « Je suis prêt quand tu l’es ».</li><li>Les notes de variante (<code>variationNote</code>) décrivent, sans « on » : « S’asseoir sur une chaise et se relever ».</li></ul><h2 id="typographie" tabindex="-1">Typographie <a class="header-anchor" href="#typographie" aria-label="Permalink to &quot;Typographie&quot;">​</a></h2><ul><li>Tapez normalement : l’apostrophe &#39; , les trois points ... et une espace ordinaire avant <code>:</code> <code>;</code> <code>!</code> <code>?</code> <code>%</code> et autour de « ». Le dépôt les corrige tout seul (apostrophe ’, points de suspension …, espaces insécables pour qu’un retour à la ligne n’isole jamais un « ? »).</li><li>Pluriels : donnez les trois formes <code>one</code>, <code>many</code>, <code>other</code>. En français <code>one</code> couvre 0 et 1 ; <code>many</code> sert aux grands nombres ronds (1 000 000) et prend le texte de <code>other</code>.</li></ul><h2 id="vocabulaire" tabindex="-1">Vocabulaire <a class="header-anchor" href="#vocabulaire" aria-label="Permalink to &quot;Vocabulaire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anglais</th><th>Français</th><th>Note</th></tr></thead><tbody><tr><td>workout</td><td>séance</td><td>Féminin : « Prévue », « Faite ».</td></tr><tr><td>session</td><td>séance</td><td>Une séance faite, dans l’historique.</td></tr><tr><td>exercise</td><td>exercice</td><td></td></tr><tr><td>set</td><td>série</td><td></td></tr><tr><td>format</td><td>format</td><td></td></tr><tr><td>work (part)</td><td>corps de séance</td><td>Le cœur de la séance, entre échauffement et retour au calme.</td></tr><tr><td>part</td><td>partie</td><td>Échauffement, corps de séance ou retour au calme.</td></tr><tr><td>rep, reps</td><td>répétition, répétitions</td><td></td></tr><tr><td>repeat (builder)</td><td>boucle</td><td>Un groupe d’étapes refait plusieurs fois. Jamais « répétition », réservé aux reps.</td></tr><tr><td>round</td><td>tour</td><td>« Tour 2 sur 4 », dans une boucle.</td></tr><tr><td>step</td><td>étape</td><td></td></tr><tr><td>block (treadmill)</td><td>bloc</td><td></td></tr><tr><td>rest</td><td>repos</td><td></td></tr><tr><td>warm-up</td><td>échauffement</td><td></td></tr><tr><td>recover</td><td>récupération</td><td></td></tr><tr><td>cool down</td><td>retour au calme</td><td></td></tr><tr><td>variation</td><td>variante</td><td></td></tr><tr><td>library</td><td>bibliothèque</td><td></td></tr><tr><td>plan (a workout for a day)</td><td>prévoir</td><td>« Prévoir pour un jour ».</td></tr><tr><td>treadmill</td><td>tapis de course, tapis</td><td>« tapis » seul une fois le contexte posé.</td></tr><tr><td>belt (treadmill)</td><td>tapis, bande</td><td>« Le tapis s’est arrêté » ; « bande » quand il faut la distinguer de la machine.</td></tr><tr><td>heart rate band</td><td>ceinture cardio</td><td></td></tr><tr><td>foot pod</td><td>pod de foulée</td><td></td></tr><tr><td>heart rate</td><td>fréquence cardiaque</td><td></td></tr><tr><td>pace</td><td>allure</td><td></td></tr><tr><td>speed</td><td>vitesse</td><td></td></tr><tr><td>incline</td><td>inclinaison</td><td></td></tr><tr><td>equipment</td><td>matériel</td><td></td></tr><tr><td>weight (load)</td><td>charge</td><td></td></tr><tr><td>no equipment</td><td>sans matériel</td><td></td></tr><tr><td>core (muscle)</td><td>abdominaux, abdos</td><td>« Abdos » sur les filtres courts.</td></tr><tr><td>core (pattern)</td><td>gainage</td><td></td></tr><tr><td>carry (pattern)</td><td>portage</td><td></td></tr><tr><td>hinge</td><td>charnière de hanche</td><td></td></tr><tr><td>rehab</td><td>rééducation</td><td></td></tr><tr><td>strength</td><td>renforcement</td><td></td></tr><tr><td>tentacle</td><td>tentacule</td><td>Masculin : « un tentacule allumé ».</td></tr><tr><td>full octopus</td><td>poulpe complet</td><td></td></tr><tr><td>Live (tab)</td><td>En direct</td><td></td></tr><tr><td>Settings</td><td>Réglages</td><td>Aussi le nom de l’app Réglages sur iPhone.</td></tr></tbody></table>',8)])])}const h=e(o,[["render",i]]);export{m as __pageData,h as default};
